    /// </remarks>
    public void SetUint(string path, ulong value)
    {
        var at = Interop.Locate(this.Object);
        var scratch = new Interop.Scratch();
        try
        {
            var cPath = scratch.Utf8(path);
            var status = Native.otio_metadata_set_uint(at.Pointer, at.Handle, cPath, value, out var error);
            GC.KeepAlive(at.Arena);
            Interop.Check(status, error);
        }
        finally
        {
            scratch.Dispose();
        }
    }

    /// <summary>
    /// Writes a point into the metadata.
    /// </summary>
    /// <remarks>
    /// <para>
    /// C: <c>otio_metadata_set_v2d</c>
    /// </para>
    /// </remarks>
    public void SetV2d(string path, V2d value)
    {
        var at = Interop.Locate(this.Object);
        var scratch = new Interop.Scratch();
        try
        {
            var cPath = scratch.Utf8(path);
            var status = Native.otio_metadata_set_v2d(at.Pointer, at.Handle, cPath, value.ToNative(), out var error);
            GC.KeepAlive(at.Arena);
            Interop.Check(status, error);
        }
        finally
        {
            scratch.Dispose();
        }
    }

    /// <summary>
    /// Writes an array of <c>len</c> nulls into the metadata, to be filled by
    /// index.
    /// </summary>
    /// <remarks>
    /// <para>
    /// C: <c>otio_metadata_set_vector</c>
    /// </para>
    /// </remarks>
    public void SetVector(string path, int len)
    {
        var at = Interop.Locate(this.Object);
        var scratch = new Interop.Scratch();
        try
        {
            var cPath = scratch.Utf8(path);
            var status = Native.otio_metadata_set_vector(at.Pointer, at.Handle, cPath, (nuint)len, out var error);
            GC.KeepAlive(at.Arena);
            Interop.Check(status, error);
        }
        finally
        {
            scratch.Dispose();
        }
    }
}

public partial class SerializableObjectWithMetadata
{
    /// <summary>
    /// The object's metadata, which is a dictionary of its own.
    /// </summary>
    /// <remarks>
    /// <para>
    /// A path names a value inside it, a step at a time, separated by dots:
    /// <c>cmx_3600.reel</c> reaches the reel of the dictionary the EDL adapter
    /// left behind, and <c>takes[0]</c> the first entry of a list.
    /// </para>
    /// <para>
    /// A path is followed, not created. Writing one step deep always works,
    /// but a deeper one needs its dictionary to exist first.
    /// </para>
    /// </remarks>
    public Metadata Metadata => new Metadata(this);
}
